import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {pathToFileURL} from 'node:url';
const root=fs.realpathSync(process.argv[2]),work=fs.realpathSync(process.argv[3]);
const accepted='24b46fce6c4557f9972c1ff4f5012b945bb5f485',candidate='a5a5072dfaac59db5285b52f2c4be5514ec16312';
const frozen='7f4bf63d1fd5ad1b997418a1b0435a4aadcd4772';
const prefix='coordination/engineering/indonesia-tanjung191-native-followup-20261014/';
const out=path.join(work,'authority');
if(process.execArgv.length||process.env.NODE_OPTIONS?.trim()||process.env.NODE_PATH?.trim())throw Error('Require plain Node');
process.env.GIT_NO_LAZY_FETCH='1';process.env.GIT_NO_REPLACE_OBJECTS='1';process.env.GIT_TERMINAL_PROMPT='0';
const count=Number(process.env.GIT_CONFIG_COUNT??0);if(!Number.isSafeInteger(count)||count<0)throw Error('Invalid Git config');
process.env.GIT_CONFIG_COUNT=String(count+1);process.env['GIT_CONFIG_KEY_'+count]='protocol.allow';process.env['GIT_CONFIG_VALUE_'+count]='never';
const git=(...args)=>execFileSync('git',['-c','protocol.allow=never','-C',root,...args],{maxBuffer:32*1024*1024});
const sha=b=>createHash('sha256').update(b).digest('hex');
if(git('rev-parse','HEAD').toString().trim()!==frozen||git('status','--porcelain','--untracked-files=no').length)throw Error('Frozen checkout changed');
if(fs.lstatSync(out,{throwIfNoEntry:false})||fs.realpathSync(path.dirname(out))!==path.dirname(out))throw Error('Require fresh ordinary output');
const inventoryRaw=fs.readFileSync(path.join(work,'execution-code.json')),inventory=JSON.parse(inventoryRaw);
if(inventory.accepted_code!==accepted||inventory.files.length!==7)throw Error('Accepted execution inventory differs');
for(const p of inventory.files){
 const body=fs.readFileSync(path.join(work,'code',p.path));
 if(body.length!==p.bytes||sha(body)!==p.sha256||!body.equals(git('show',accepted+':'+p.path)))throw Error('Accepted code differs: '+p.path);
}
const entry=fs.readFileSync(process.argv[1]),executionBytes=entry.length+inventory.total_code_bytes+inventoryRaw.length;
const {ImmutableReader,processingAllowance}=await import(pathToFileURL(path.join(work,'code/scripts/check-effective-geographic-regression.mjs')).href);
const {constructOriginalAuthority}=await import(pathToFileURL(path.join(work,'code/scripts/delivery-handoff-advance.mjs')).href);
const observation={availableBytes:process.availableMemory(),currentRssBytes:process.memoryUsage().rss,concurrentReservedBytes:1048576};
const allowance=processingAllowance({...observation,phaseBytes:512*1024*1024,rssBytes:512*1024*1024});
const runtimeBytes=fs.statSync(fs.realpathSync(process.execPath)).size;
const reader=new ImmutableReader(root,candidate,{allowance,executionBytes,runtimeBytes});
const inputs={source_evidence:{commit:candidate,path:prefix+'source-evidence.json'},native_patch:{commit:candidate,path:prefix+'candidate-native-patch.json'}};
// The existing reader owns exact encoded/decoded/parse charging at every read.
// This pre-call inventory additionally bounds the complete declared input union.
const operandDescriptors=Object.values(inputs).map(p=>reader.descriptor(p.path,p.commit));
reader.used+=6*operandDescriptors.reduce((n,p)=>n+p.bytes,0);
reader.checkMemory();
const input=reader.json(inputs.source_evidence.path);
const proposed=reader.json(inputs.native_patch.path);
const pins=[input.catalogue,input.physical_evidence,input.physical_input,input.physical_reproduction,input.owner_roster,input.native_latitudes,...input.families.flatMap(f=>f.parts)];
const unique=new Map(pins.map(p=>[p.commit+':'+p.path,p]));
const prospectivelyModeled=reader.used+[...unique.values()].reduce((n,p)=>n+p.bytes+(p.decoded_bytes??0)+6*(p.decoded_bytes??p.bytes),0)+8*1024*1024;
if(prospectivelyModeled>=allowance.phaseBytes)throw Error('Complete prospective phase exceeds fresh allowance');
const admitted={version:1,kind:'fresh-tanjung191-native-reader-admission',observed_at:new Date().toISOString(),accepted_code:accepted,input_commit:candidate,observation,allowance,runtime_bytes:runtimeBytes,execution_bytes:executionBytes,operand_descriptors:operandDescriptors,prospectively_modeled_phase_bytes:prospectivelyModeled,wall_seconds:60,output_bytes:reader.outputBytes,inputs};
fs.writeFileSync(path.join(work,'native-admission.json'),JSON.stringify(admitted,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({status:'fresh-admission',...admitted}));
const started=process.hrtime.bigint();
const result=constructOriginalAuthority(reader,inputs);reader.checkMemory();
const rows=result.ledger_rows;
const cells=rows.reduce((n,row)=>n+row.native_rows.reduce((s,r)=>s+r.runs.reduce((a,run)=>a+run[1]-run[0],0),0),0);
if(cells!==191||rows.length!==1||rows[0].pixelIndex!==23055||rows[0].target_id!=='gb:IDN:ADM2:22746128B73074683492420')throw Error('Qualified scope differs from requested Tanjung191');
if(JSON.stringify(rows[0].native_rows)!==JSON.stringify(proposed.rows))throw Error('Constructor changed requested cell tuples');
const products={...result.products,'qualified-ledger-rows.json':Buffer.from(JSON.stringify(rows,null,2)+'\n')};
const peak=process.resourceUsage().maxRSS*1024;
const receipt={version:1,kind:'existing-source-target-native-constructor-result',accepted_code:accepted,input_commit:candidate,frozen_delivery_head:frozen,inputs,observation,allowance,runtime_bytes:runtimeBytes,prospectively_modeled_phase_bytes:prospectivelyModeled,charged_phase_bytes:reader.used,qualified_cells:cells,component_ids:result.component_ids,rule_sha256:result.rule_sha256,elapsed_seconds:Number(process.hrtime.bigint()-started)/1e9,normalized_node_lifetime_peak_rss_bytes:peak,observed_peak_within_allowance:peak<=allowance.rssBytes,entry:{bytes:entry.length,sha256:sha(entry)},code:inventory.files,inventory:[...reader.inventory.values()],limitations:result.limitations,limits:['Actual stock source-target constructor; complete native source coverage and retained reconstruction residual interiors/boundary ties checked without source/GSHHG replay.','Qualification is not current-owner-zero, selected consumption, acceptance, delivery or territorial/semantic certification.','Bintan3088repair and all4760source-relative holds remain excluded.','Original source wrapper limitations and physical producer RSS overrun remain unchanged.','Reader uses its existing complete phase/RSS checks; measured child lifetime RSS is not aggregate process-tree RSS or OS enforced containment.']};
products['receipt.json']=Buffer.from(JSON.stringify(receipt,null,2)+'\n');
if(Object.values(products).some(b=>b.length>reader.outputBytes)||Object.values(products).reduce((n,b)=>n+b.length,0)>reader.outputBytes)throw Error('Complete qualification outputs exceed reserve');
if(peak>allowance.rssBytes||git('rev-parse','HEAD').toString().trim()!==frozen)throw Error('Observed RSS or frozen head changed');
fs.mkdirSync(out);for(const [name,body] of Object.entries(products))fs.writeFileSync(path.join(out,name),body,{flag:'wx'});
console.log(JSON.stringify({status:'native-qualified',qualified_cells:cells,components:result.component_ids.length,charged_phase_bytes:reader.used,allowance,peak_rss_bytes:peak,elapsed_seconds:receipt.elapsed_seconds}));
